#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)


#define MAX_FLAME_STEPS 50
#define MAX_NOISE_OCTAVES 3
#define NUM_LIGHTS 5

// lighting constants and structs =======================================================

const float specularPower = 32.0;

const vec3 ambientLightColor = vec3(1.0, 1.0, 1.0);
const float ambientLightIntensity = 0.5;

const float emissiveIntensity = 9.0;
const float glowSpread = 0.5;

const float reflectivity = 0.5;

struct Light {
    int type;        // 0: point light, 1: directional light
    vec3 position;   // used if point light
    vec3 direction;  // used if directional light
    vec3 color;      // light color
    float intensity; // light intensity
};

Light lights[NUM_LIGHTS] = Light[](
    Light( // point light
        0,
        vec3(2.0, 4.0, -2.0),
        vec3(0.0),
        vec3(1.0, 1.0, 1.0),
        1.0
    ),
    Light( // directional Light
        1,
        vec3(0.0),
        normalize(vec3(-1.0, -1.0, -1.0)),
        vec3(1.0, 1.0, 1.0),
        4.0
    ),
    Light( // green box as point light
        0,
        vec3(0.9, 0.0, 0.0),
        vec3(0.0),
        vec3(0.1, 0.9, 0.1),
        emissiveIntensity
    ),
    Light( // red sphere as point light
        0,
        vec3(-0.4, 0.4, 0.5),
        vec3(0.0),
        vec3(0.9, 0.1, 0.1),
        emissiveIntensity
    ),
    Light( // blue sphere as point light
        0,
        vec3(-0.8, 0.4, -0.75),
        vec3(0.0),
        vec3(0.1, 0.1, 0.9),
        emissiveIntensity
    )
);

// flame constants ======================================================================
const float flameWidth = 2.3;
const float noiseScale = 2.5;
const float noiseSpeed = 0.05;
const float flameIntensity = 0.5;
const float noiseGain = 0.5;
const float noiseMult = 0.5;
const float colorFlicker = 2.5;

// movement
const float greenBoxSpeed = 1.4;
const float redSphereSpeed = -1.4;
const float blueSphereSpeed = 2.2;

const vec3 greenBoxRange = vec3(1.3, -0.4, 1.0);
const vec3 redSphereRange = vec3(1.0, 1.0, 1.0);
const vec3 blueSphereRange = vec3(-0.4, 1.1, 0.5);

const vec3 greenBoxCenter = vec3(0.0, -0.5, 0.0);
const vec3 redSphereCenter = vec3(0.0, 0.0, 0.0);
const vec3 blueSphereCenter = vec3(0.0, 0.0, 0.0);

//=======================================================================================
// utility functions

// random num generator function from LYGIA Shader Library
// https://lygia.xyz/generative/srandom
float rand3D(in vec3 p) {
  return fract(sin(dot(p.xyz, vec3(70.9898, 78.233, 32.4355))) * 43758.5453123);
}

// modified 3D noise and fbm based on Morgan McGuire
// https://www.shadertoy.com/view/4dS3Wd
float noise3D(in vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);

    f = f * f * (3.0 - 2.0 * f);

    float n = mix(mix(mix(rand3D(i + vec3(0,0,0)), rand3D(i + vec3(1,0,0)), f.x),
                      mix(rand3D(i + vec3(0,1,0)), rand3D(i + vec3(1,1,0)), f.x), f.y),
                  mix(mix(rand3D(i + vec3(0,0,1)), rand3D(i + vec3(1,0,1)), f.x),
                      mix(rand3D(i + vec3(0,1,1)), rand3D(i + vec3(1,1,1)), f.x), f.y), f.z);

    return n * 2.0 - 1.0; // outputs symmetric noise [-1, 1)
}

float fbm3D(in vec3 p) {
    float v = 0.0;
    float a = 0.5;
    float f = 1.0;

    for(int i = 0; i < MAX_NOISE_OCTAVES; i++) {
        v += a * noise3D(p * f + iTime * 0.1);
        a *= 0.5;
        f *= 2.0;
    }

    return v;
}

//=======================================================================================
// SDF for flame effect
float flameDist(in vec3 p, in vec3 center, in float radius, in vec3 velocity) {
    // get direction opposite to velocity for trailing flames
    vec3 dir = normalize(-velocity);
    // get projected distance along flame direction
    vec3 v = p - center;
    float projDist = dot(v, dir);

    // deform radius to get narrower from the center, and elongate towards velocity
    float stretch = length(velocity) * 0.5;
    radius *= (1.0 - (max(0.0, -projDist)) * 0.5);
    radius *= mix(1.0, flameWidth, max(0.0, projDist * stretch));

    // animated noise with time offset for burning effect
    float t = iTime * noiseSpeed;
    float noise = fbm3D((p + t) * noiseScale) * noiseMult + noiseGain;

    // return final signed distance + noise
    return (length(v)) ;
}


//=======================================================================================
// calculate combined diffuse, specular, ambient lighting
vec3 calculateLighting(in vec3 albedo, in vec3 normal, in vec3 hitPos, in vec3 viewDir)
{
    // ambient lighting
    vec3 lighting = ambientLightColor * ambientLightIntensity * albedo;

    for(int i = 0; i < NUM_LIGHTS; ++i)
    {
        vec3 lightDir;
        float attenuation = 1.0;

        // calculate light direction and attenuation
        if(lights[i].type == 0) // point Light
        {
            lightDir = normalize(lights[i].position - hitPos);
            float distance = length(lights[i].position - hitPos);
            attenuation = 1.0 / (distance * distance);
        }
        else if(lights[i].type == 1) // directional Light
        {
            lightDir = normalize(-lights[i].direction);
        }

        // only proceed if surface is facing light
        float NdotL = max(dot(normal, lightDir), 0.0);
        if(NdotL > 0.0) {
            // diffuse component (lambertian)
            vec3 diffuse = lights[i].color * NdotL * lights[i].intensity;

            // specular component (phong)
            vec3 reflectDir = reflect(-lightDir, normal);
            float spec = pow(max(dot(viewDir, reflectDir), 0.0), specularPower);
            vec3 specular = lights[i].color * spec * lights[i].intensity;

            lighting += (diffuse * albedo + specular) * attenuation;
        }
    }

    return lighting;
}

//=======================================================================================
// get final pixel color using lighting and environment reflections
vec3 ShadePixel (in vec3 albedo, in vec3 normal, in vec3 hitPos, in vec3 viewDir)
{
    // point + directional light + ambient lighting 
	vec3 lighting = calculateLighting(albedo, normal, hitPos, viewDir);

    // environment mapped reflections
    vec3 reflectV = reflect(-viewDir, normal); // point direction towards surface 
    vec3 map;
    lighting = mix(lighting, map, reflectivity);

    return lighting;
}

//=======================================================================================
bool RayIntersectAABox  (in vec3 boxMin, in vec3 boxMax, in vec3 rayPos, in vec3 rayDir, out vec3 hitPos, out vec3 normal, inout float maxTime)
{
    vec3 boxCenter = (boxMin+boxMax)*0.5;
	vec3 roo = rayPos - boxCenter;
    vec3 rad = (boxMax - boxMin)*0.5;

    vec3 m = 1.0/rayDir;
    vec3 n = m*roo;
    vec3 k = abs(m)*rad;

    vec3 t1 = -n - k;
    vec3 t2 = -n + k;

    vec2 time = vec2( max( max( t1.x, t1.y ), t1.z ),
                 min( min( t2.x, t2.y ), t2.z ) );

    // if the time is beyond the maximum allowed bail out (we hit somethign else first!)
    if (time.x > maxTime)
        return false;

    // if time invalid or we hit from inside, bail out
    if (time.y < time.x || time.x < 0.0)
        return false;

    // calculate surface normal
    hitPos = rayPos + rayDir * time.x;   
    vec3 hitPosRelative = hitPos - boxCenter;
    vec3 hitPosRelativeAbs = abs(hitPosRelative);
    vec3 distToEdge = abs(hitPosRelativeAbs - rad);

    float closestDist = 1000.0;
    for(int axis = 0; axis < 3; ++axis)
    {
        if (distToEdge[axis] < closestDist)
        {
            closestDist = distToEdge[axis];
            normal = vec3(0.0);
            if (hitPosRelative[axis] < 0.0)
                normal[axis] = -1.0;
            else
                normal[axis] = 1.0;
        }
    }        

    // store the collision time as the new max time
    maxTime = time.x;
    return true;
}

//=======================================================================================
bool RayIntersectSphere (in vec4 sphere, in vec3 rayPos, in vec3 rayDir, out vec3 hitPos, out vec3 normal, inout float maxTime)
{
    if (sphere.w <= 0.0)
        return false;

	//get the vector from the center of this circle to where the ray begins.
	vec3 m = rayPos - sphere.xyz;

    //get the dot product of the above vector and the ray's vector
	float b = dot(m, rayDir);

	float c = dot(m, m) - sphere.w * sphere.w;

	//exit if r's origin outside s (c > 0) and r pointing away from s (b > 0)
	if(c > 0.0 && b > 0.0)
		return false;

	//calculate discriminant
	float discr = b * b - c;

	//a negative discriminant corresponds to ray missing sphere
	if(discr < 0.0)
		return false;

	//ray now found to intersect sphere, compute smallest t value of intersection
	float collisionTime = -b - sqrt(discr);

	//if t is negative, ray started inside sphere so clamp t to zero and remember that we hit from the inside
	if(collisionTime < 0.0)
        return false;

    // if the time is beyond the maximum allowed bail out (we hit somethign else first!)
    if (collisionTime > maxTime)
        return false;

    // store the collision time as the new max time
    maxTime = collisionTime;

	//compute the point of intersection
	hitPos = rayPos + rayDir * collisionTime;    

   	// calculate the normal
	normal = hitPos - sphere.xyz;
	normal = normalize(normal); 

	return true;
}

//=======================================================================================
void TraceRay (in vec3 rayPos, in vec3 rayDir, inout vec3 pixelColor)
{
    // albedo colors used for objects and flames
    vec3 greenBoxAlbedo = vec3(0.1, 0.9, 0.1);
    vec3 redSphereAlbedo = vec3(0.9, 0.1, 0.1);
    vec3 blueSphereAlbedo = vec3(0.1, 0.1, 0.9);

    float maxRayHitTime = 1000.0;
    bool hit = false;
    vec3 hitPos;    
    vec3 normal;            
    vec3 albedo;
    vec3 viewDir;

    // variables to keep track of closest hit
    vec3 closestHitPos;
    vec3 closestNormal;
    vec3 closestAlbedo;

    // variables for flame ray marching
    vec3 marchPos = rayPos;
    float stepSize = 0.1;
    vec3 flameAccum = vec3(0.0);
    float opacity = 1.0;

    // animated positions for each object
    vec3 greenBoxPos = greenBoxCenter + vec3(
        cos(iTime * greenBoxSpeed) * greenBoxRange.x,
        sin(iTime * greenBoxSpeed) * greenBoxRange.y,
        sin(iTime * greenBoxSpeed) * greenBoxRange.z
    );
    vec3 redSpherePos = redSphereCenter + vec3(
        cos(iTime * redSphereSpeed) * redSphereRange.x,
        sin(iTime * redSphereSpeed) * redSphereRange.y,
        sin(iTime * redSphereSpeed) * redSphereRange.z
    );
    vec3 blueSpherePos = blueSphereCenter + vec3(
        sin(iTime * blueSphereSpeed) * blueSphereRange.x,
        cos(iTime * blueSphereSpeed) * blueSphereRange.y,
        cos(iTime * blueSphereSpeed) * blueSphereRange.z
    );

	// green box
    if (RayIntersectAABox(
        greenBoxPos + vec3(-0.5, -0.3, -0.5),
        greenBoxPos + vec3(0.5, 0.3, 0.5),
        rayPos, rayDir, hitPos, normal, maxRayHitTime))
    {
        hit = true;
        closestHitPos = hitPos;
        closestNormal = normal;
        closestAlbedo = greenBoxAlbedo;
    }

    // red sphere
    if (RayIntersectSphere(
        vec4(redSpherePos, 0.5),
        rayPos, rayDir, hitPos, normal, maxRayHitTime))
    {
        hit = true;
        closestHitPos = hitPos;
        closestNormal = normal;
        closestAlbedo = redSphereAlbedo;  
    }

    // blue sphere
    if (RayIntersectSphere(
        vec4(blueSpherePos, 0.25),
        rayPos, rayDir, hitPos, normal, maxRayHitTime))
    {
        hit = true;
        closestHitPos = hitPos;
        closestNormal = normal;
        closestAlbedo = blueSphereAlbedo;     
    }

    // velocities of each moving object
    vec3 greenBoxVel = vec3(
        -sin(iTime * greenBoxSpeed) * greenBoxRange.x * greenBoxSpeed,
        cos(iTime * greenBoxSpeed) * greenBoxRange.y * greenBoxSpeed,
        cos(iTime * greenBoxSpeed) * greenBoxRange.z * greenBoxSpeed
    );
    vec3 redSphereVel = vec3(
        -sin(iTime * redSphereSpeed) * redSphereRange.x * redSphereSpeed,
        cos(iTime * redSphereSpeed) * redSphereRange.y * redSphereSpeed,
        cos(iTime * redSphereSpeed) * redSphereRange.z * redSphereSpeed
    );
    vec3 blueSphereVel = vec3(
        cos(iTime * blueSphereSpeed) * blueSphereRange.x * blueSphereSpeed,
        -sin(iTime * blueSphereSpeed) * blueSphereRange.y * blueSphereSpeed,
        -sin(iTime * blueSphereSpeed) * blueSphereRange.z * blueSphereSpeed
    );

    // create volumetric flames by marching along ray
    for(int i = 0; i < MAX_FLAME_STEPS; i++) {
        // signed distances to flames from each object
        float greenBoxFlame = flameDist(marchPos, greenBoxPos, 0.7, greenBoxVel);
        float redSphereFlame = flameDist(marchPos, redSpherePos, 0.6, redSphereVel);
        float blueSphereFlame = flameDist(marchPos, blueSpherePos, 0.5, blueSphereVel);

        // get flame density based on closest flame influence
        float minFlame = min(min(greenBoxFlame, redSphereFlame), blueSphereFlame);
        float flameDensity = smoothstep(0.3, 0.0, minFlame);

        // assign flame color
        vec3 flameCol;
        if(minFlame == greenBoxFlame) {
            flameCol = greenBoxAlbedo;
        }
        else if(minFlame == redSphereFlame) {
            flameCol = redSphereAlbedo;
        }
        else {
            flameCol = blueSphereAlbedo;
        }

        // only accumulate flame color/transparency if positive flame density
        if(flameDensity > 0.0) {
            flameCol *= 1.0 + noise3D(vec3(iTime * colorFlicker));
            flameAccum += flameCol * flameIntensity * flameDensity * opacity;

            // accumulating opacity inspired by Perlin,K.,& Hoffert,E.M.(1989)
            // https://dl.acm.org/doi/pdf/10.1145/74334.74359
            opacity *= (1.0 - flameDensity * 0.01);
        }

        marchPos += rayDir * stepSize;
    }

    // if no object hit blend flame with background
    if (!hit) {
        vec3 map ; // darken background
        pixelColor = map * opacity + flameAccum;
        return;
    }

    // update hit details with closest intersection
    hitPos = closestHitPos;
    viewDir = normalize(-rayDir);

    // apply shading and flame color to hit point
    vec3 color = ShadePixel(closestAlbedo, closestNormal, hitPos, viewDir);
    pixelColor = color * opacity + flameAccum;
}

void mainImage(out vec4 O, vec2 C)
{
    O=vec4(0);
    vec3 p,q,r=iResolution,
    d=normalize(vec3((C*2.-r.xy)/r.y,1));  
        // update emissive glow light positions to move with objects
    lights[2].position = greenBoxCenter + vec3(
        cos(iTime * greenBoxSpeed) * greenBoxRange.x,
        sin(iTime * greenBoxSpeed) * greenBoxRange.y,
        sin(iTime * greenBoxSpeed) * greenBoxRange.z);

    lights[3].position = redSphereCenter + vec3(
        cos(iTime * redSphereSpeed) * redSphereRange.x,
        sin(iTime * redSphereSpeed) * redSphereRange.y,
        sin(iTime * redSphereSpeed) * redSphereRange.z);

    lights[4].position = blueSphereCenter + vec3(
        sin(iTime * blueSphereSpeed) * blueSphereRange.x,
        cos(iTime * blueSphereSpeed) * blueSphereRange.y,
        cos(iTime * blueSphereSpeed) * blueSphereRange.z);

    //----- camera setup
    vec2 mouse = iMouse.xy / iResolution.xy;

    vec3 cameraAt 	= vec3(0.0,0.0,0.0);

    float angleX = iMouse.z > 0.0 ? 6.28 * mouse.x : 0.0;
    float angleY = iMouse.z > 0.0 ? (mouse.y * 6.28) : 0.0;

    vec3 cameraPos	= (vec3(sin(angleX)*cos(angleY), sin(angleY), cos(angleX)*cos(angleY))) * 4.0;

    vec3 cameraFwd  = normalize(cameraAt - cameraPos);
    vec3 cameraLeft  = normalize(cross(normalize(cameraAt - cameraPos), vec3(0.0,sign(cos(angleY)),0.0)));
    vec3 cameraUp   = normalize(cross(cameraLeft, cameraFwd));

    float cameraViewWidth	= 6.0;
    float cameraViewHeight	= cameraViewWidth * iResolution.y / iResolution.x;
    float cameraDistance	= 4.0;  // intuitively backwards!    

	vec2 rawPercent = (C.xy / iResolution.xy);
	vec2 percent = rawPercent - vec2(0.5,0.5);

	vec3 rayPos;
	vec3 rayTarget;

	// if the mouse button is down do orbit camera
	if( iMouse.z > 0.0 ) {
		rayTarget = (cameraFwd * cameraDistance)
				  + (cameraLeft * percent.x * cameraViewWidth)
		          + (cameraUp * percent.y * cameraViewHeight);

		rayPos = cameraPos;
	}
	// else handle the case of the mouse button not being down
	else {
		rayPos = vec3(0.0,3.0,-3.0);
		vec3 f = normalize(cameraAt - rayPos);
		vec3 l = normalize(cross(f,vec3(0.0,1.0,0.0)));
		vec3 u = normalize(cross(l,f));

		rayTarget = (f * cameraDistance)
				  + (l * percent.x * cameraViewWidth)
		          + (u * percent.y * cameraViewHeight);		
	}

	//----- ray trace
	vec3 rayDir = normalize(rayTarget);

    // initialze ray color to the cube map
    vec3 pixelColor ;

    // ray trace
	TraceRay(rayPos, rayDir, pixelColor);

    // add glow effect around emissive light objects
    for(int i = 2; i < NUM_LIGHTS; ++i)
    {
        // get shortest distance from current light to ray
        vec3 p = lights[i].position;
        vec3 v = p - rayPos;
        float t = max(dot(v, rayDir), 0.0);
        float distance = length((rayPos + rayDir * t) - p);

        // add diffused glow using a gaussian falloff
        // https://paroj.github.io/gltut/Illumination/Tut11%20Gaussian.html
        float glow = exp(-pow(distance / glowSpread, 2.0));
        pixelColor += lights[i].color * glow;
    }

    for(float i=0.,a,s,e,g=0.;
        ++i<70.;
        O.xyz+=mix(vec3(1),H(g*.1),.8)*1./e/8e3
    )
    {
        p=g*d;


    // output sRGB corrected pixel
        a=30.;
        p=mod(p-a,a*2.)-a;
        s=3.;
        for(int i=0;i++<8;){
            p=.3-abs(p);
              p.xz+=cameraFwd.xz;
            p.x<p.z?p=p.zyx:p;
            p.z<p.y?p=p.xzy:p;
            s*=e=2.2+sin(iTime*.01)*.1;
            p=abs(p)*e-
                vec3(
                    5.*3.,
                    120,
                    2.*5.
                 )+pixelColor;
         }
         g+=e=length(p.yzzz)/s;
    }
    O*=vec4(pixelColor*1.,1.);
}
